mapper.update:
UPDATE work
title = #{title}, summary = #{summary}, detail = #{detail}, category_id = #{categoryId}, tags = #{tags}, cover_url = #{coverUrl}, demo_url = #{demoUrl}, video_url = #{videoUrl}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT w.*, up.nickname AS owner_name, up.avatar_url AS owner_avatar
FROM work w LEFT JOIN user_profile up ON w.owner_id = up.account_id
WHERE w.id = #{id}

SELECT w.*, up.nickname AS owner_name, up.avatar_url AS owner_avatar
FROM work w LEFT JOIN user_profile up ON w.owner_id = up.account_id
WHERE w.owner_id = #{ownerId}
ORDER BY w.create_time DESC
LIMIT #{offset}, #{limit}

SELECT w.*, up.nickname AS owner_name, up.avatar_url AS owner_avatar, (SELECT COUNT(*) FROM favorite f WHERE f.target_type='WORK' AND f.target_id=w.id) AS favorite_count, (SELECT COUNT(*) FROM comment c WHERE c.target_type='WORK' AND c.target_id=w.id) AS comment_count FROM work w LEFT JOIN user_profile up ON w.owner_id = up.account_id WHERE w.audit_status = 'APPROVED' AND w.visibility_status = 'PUBLIC' AND w.category_id = #{categoryId}
AND (w.title LIKE CONCAT('%', #{keyword}, '%') OR w.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY
w.create_time DESC w.create_time DESC
LIMIT #{offset}, #{limit}

SELECT w.*, up.nickname AS owner_name, up.avatar_url AS owner_avatar
FROM work w LEFT JOIN user_profile up ON w.owner_id = up.account_id

    w.audit_status = #{auditStatus}

ORDER BY w.create_time DESC
LIMIT #{offset}, #{limit}
